head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.v_SaveKind = ""; // 신규,수정 구분
scwin.vBzProcsNo = ""; // 업무처리번호
scwin.vIsuCd = ""; // 종목코드
scwin.vListBzTpCd = ""; // 상장업무구분코드 (781 : 신규상장, 784 : 추가상장, 789 : 수량감소)
scwin.vDisclsYn = ""; // 공시여부
// 화면ID

// Transaction 처리코드
scwin.TR_JOB;

/**
 * @method
