    if (!$c.lcd.fn_check_delete_discls(dts_BzProcsNo, scwin.vBzProcsNo)) return;
    scwin.TR_JOB = 'D';

    // Transaction 처리전 안내문구
    if (!$c.lcd.fn_isProcess(scwin.TR_JOB)) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    let vScrenId = "SCREN_ID=" + "ULDSTF70030_N2.xml";
    let vScrenTpId = "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
    let vSrvMethod = "&method=deleteQtyChange";

    // 상장업무구분코드 있는 경우에만 삭제 처리 함
    // if (vListBzTpCd != "") {
    trs_Save.KeyName = "toinb_dataid4";
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : TR_JOB_DELETE,
    //     LIST_BZ_TP_CD : scwin.vListBzTpCd,
    //     BZ_PROCS_NO : scwin.vBzProcsNo,
    //     ISU_CD : scwin.vIsuCd,
    //     ISUR_CD : dts_Isu.getCellData(1, "ISUR_CD"),
    //     ACPT_NO : js_emp_no,
    //     LD_MKT_TP_CD : "1",
    //     TRANSTR_EMP_NO : js_emp_no
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/digital/DigitalListinvstg.do",
        ref : "dts_Isu",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    // }

};

/**
 * @method
 * @name checkModifyDts
 * @description 안내문작성 시, 수정사항 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkModifyDts = async function() {
    let rtn = false;
    if ($c.cp.isModified(dts_Isu) === false) {
        rtn = true;
    } else {
        await $c.win.alert("변경된 내용이 있습니다. [수정] 후 진행하세요.");
        rtn = false;
    }
    return rtn;
};

/**********************************************
 * 함수명 : fn_dscl()
 * 설명    : 변경상장 > 기타수량감소 > 상세보기 > 안내문 작성
 ***********************************************/
scwin.getPar, scwin.setPar;

/**
 * @method
 * @name dscl
 * @description dscl 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dscl = async function() {
    const OldGet = scwin.getPar;
    const OldSet = scwin.setPar;
    const cCtnt = "";
    if (await scwin.checkModifyDts() === false) {
        return;
    }
    scwin.getPar = function(arr, param_dts_isu, param_dts_mst, param_dts2) {
        arr[0] = "69565B";
        arr[1] = scwin.vBzProcsNo;
        arr[2] = dts_Isu.getCellData(1, "ISUR_CD");
        arr[3] = '1';
        arr[4] = ""; // fn_getQtyChgDisclsCtnt(); //ctnt
        // arr[5] = vIsuAbbrv; //add  title
        arr[5] = txb_ISU_NM.getValue(); // add  title

        const sDate = scwin.dateForm(edt_CHG_LIST_DD.getValue());
        $c.stf.copyDataSet(dts_Isu, param_dts_isu);
        $c.stf.copyDataSet(dts_Isu, param_dts_mst);
        // param_dts_mst.NameString(param_dts_mst.RowPosition, "TGT_NM") = Isur_nm ;

        // 파라미터 ds 만 값 변경
        param_dts_isu.setCellData(param_dts_isu.getFocusedRowIndex(), "CHG_LIST_DD", sDate);
        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "CHG_LIST_DD", sDate);
        return arr.length;
    };
    scwin.setPar = function(arr) {

    };
    const wth = 750;
    const hgt = 820;
    const pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    const options = {
        id: "ULDSTF92024",
        title: "변경상장 수량변경 안내문작성",
        type: "browserPopup",
        width: wth,
        height: hgt,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/listingcommon/ULDSTF92024.gfm", options);
    scwin.getPar = OldGet;
    scwin.setPar = OldSet;

    // 안내문팝업 후 '닫기'나 '안내문전송' 후에 Popup Close 및 Parent Refresh 함
    $c.frame.path("../").fn_list_qty_chglist_sync();
};

/**
 * @method
 * @name getQtyChgDisclsCtnt
 * @description 안내문작성 서식 (수량변경)
 * @returns {void}
 * @hidden N
 */
scwin.getQtyChgDisclsCtnt = function() {
    let vCtnt = "";
    let indecShrs = 0;
    let chgPreShrs = 0;
    let chgAfshrs = 0;
    const lpHdQty = 0;

    // Comma 처리
    indecShrs = (parseInt(txb_INCDEC_APPL_LIST_SHRS.getValue()) < 0) ? $c.stf.addCommaMinus(txb_INCDEC_APPL_LIST_SHRS.getValue()) : $c.stf.addComma(txb_INCDEC_APPL_LIST_SHRS.getValue());
    chgPreShrs = (parseInt(txb_CHG_PRE_LIST_SHRS.getValue()) < 0) ? $c.stf.addCommaMinus(txb_CHG_PRE_LIST_SHRS.getValue()) : $c.stf.addComma(txb_CHG_PRE_LIST_SHRS.getValue());
    chgAfshrs = (parseInt(txb_CHG_AF_LIST_SHRS.getValue()) < 0) ? $c.stf.addCommaMinus(txb_CHG_AF_LIST_SHRS.getValue()) : $c.stf.addComma(txb_CHG_AF_LIST_SHRS.getValue());
    // lpHdQty = (parseInt(txb_LP_HD_QTY.text) < 0) ? addCommaMinus(txb_LP_HD_QTY.text) : addComma(txb_LP_HD_QTY.text);

    vCtnt += "[공시제목] 신종증권 변경상장";
    vCtnt += "\r\n\r\n";
    vCtnt += "[본문내용]";
    vCtnt += "\r\n\r\n";
    vCtnt += "◎ " + txb_ISU_NM.getValue() + "  변경상장(수량감소)";
    vCtnt += "\r\n\r\n";
    vCtnt += "1. 종목명 : " + txb_ISU_NM.getValue(); // getObjectValue(txb_ISU_NM);
    vCtnt += "\r\n\r\n";
    vCtnt += "2. 감소수량 : " + indecShrs;
    vCtnt += "\r\n\r\n";
    vCtnt += "3. 상장증권수 : 변경상장전 " + chgPreShrs + " → 변경상장후 " + chgAfshrs;
    vCtnt += "\r\n\r\n";
    vCtnt += "4. 변경상장일 : " + scwin.dateForm(edt_CHG_LIST_DD.getValue());
    vCtnt += "\r\n\r\n";
    return vCtnt;
};

/**
 * @method
 * @name dateForm
 * @description 년월일 포맷 맞춤 (안내문 작성에서 사용)
 * @param {String} pStr pStr
 * @returns {void}
 * @hidden N
 */
scwin.dateForm = function(pStr) {
    let str = "";
    if (pStr === "") {
        str = "★★★★년" + "★★월" + "★★일";
    } else {
        str = pStr.substring(0, 4) + "년 " + pStr.substring(4, 6) + "월 " + pStr.substring(6, 8) + "일";
    }
    return str;
};

/**
 * @method
 * @name parentRefresh
 * @description Parent 화면 Refresh()
 * @returns {void}
 * @hidden N
 */
scwin.parentRefresh = function() {
    // Parent 신청내역 화면 Refresh
    let parentWin = $c.frame.path("../");
    parentWin.fn_list_qty_chglist_sync();
};

/**
 * @method
 * @name f_FormAllControlDisabled
 * @description 컨트롤 비활성화
 * @returns {void}
 * @hidden N
 */
scwin.f_FormAllControlDisabled = function() {
    // 버튼:삭제,안내문전송
    btn_QtyIsuDel.src = "../img/btn_RcvdocDel_d.gif";
    btn_QtyIsuDel.setDisabled(true);
    btn_QtyIsuDscl.src = "../img/btn_make_info_d.gif";
    btn_QtyIsuDscl.setDisabled(true);

    // 텍스트:증감증권수,LP보유량
    txb_INCDEC_APPL_LIST_SHRS.setReadOnly(true);
    txb_LP_HD_QTY.setReadOnly(true);

    // 달력:발행일,신규상장일
    edt_QTY_DEC_DD.setReadOnly(true);
    img_QtyDecDD.setDisabled(true);
    img_QtyDecDD.src = "../img/icn_calendar_d.gif";
    edt_CHG_LIST_DD.setReadOnly(true);
    img_CHG_LIST_DD.setDisabled(true);
    img_CHG_LIST_DD.src = "../img/icn_calendar_d.gif";
};

