/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    let parentWin = $c.frame.path("../");

    // Transaction 구분: 신규(N), 수정(U), 삭제(D)
    scwin.v_SaveKind = parentWin.vIsuChgKind;

    // vBzProcsNo = parentWin.clickBzProcsNo;  // 업무처리번호
    scwin.vIsuCd = parentWin.clickIsuCd; // 종목코드
    scwin.vListBzTpCd = parentWin.clickBzTpCd; // 상장유형코드
    // vIsurCd        = parentWin.clickIsurCd;       // 상장인코드
    // vIsurNm       = parentWin.clickIsurNm;       //  상장인명
    scwin.vDisclsYn = parentWin.clickDisclsYn; // 공시여부

    // 파일 첨부 dataset header

    // dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    if (scwin.v_SaveKind === "N") {
        // 신규일 경우
        // 종목코드 Textbox 설정 및 종목코드 정보 조회
        await scwin.selectIsurInit();

        // 값이 존재하지 않는다면
        // 수량감소(789) 로 셋팅
        if (scwin.vListBzTpCd === "") {
            scwin.vListBzTpCd = "789";
        }
        label_b1.hide();
        label_b2.hide();
        label_b3.hide();
    } else if (scwin.v_SaveKind === "U") {
        // 수정일 경우

        scwin.vBzProcsNo = parentWin.clickBzProcsNo;
        // 세부내역 조회
        await scwin.selectIsurDetail();
        label_a1.hide();
        label_a2.hide();
        label_a3.hide();
    }

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, scwin.saveQtyIsurNew); // 저장
    buttonSet.setUpdateInfo(btn_Update, scwin.saveQtyIsurUpdate); // 수정
    buttonSet.setDeleteInfo(btn_Delete, scwin.saveQtyIsurDelete); // 삭제
    buttonSet.setDsclInfo(btn_Dscl, scwin.dscl); // 안내문작성

    // textbox, 첨부파일
    // 상장업무구분코드(신규상장:781)
    if (scwin.vListBzTpCd === "781") {
        txb_ApplType.setValue("신규상장");
        txb_QtyDecDD.setValue("발행일");
        txb_ListDd.setValue("신규상장일");
        panel_file.style.visibility = "hidden";
        panel_guide.style.visibility = "hidden";
        // 상장업무구분코드(추가상장:784)

    } else if (scwin.vListBzTpCd === "784") {
        txb_ApplType.setValue("추가상장");
        txb_QtyDecDD.setValue("추가발행일");
        txb_ListDd.setValue("추가상장일");
        panel_file.style.visibility = "hidden";
        panel_guide.style.visibility = "hidden";
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description 저장메세지, 부모화면 Refresh, 화면 닫기
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    // 저장메세지, 부모화면 Refresh, 화면 닫기
    $c.lcd.fn_alertMsg('S');
    scwin.parentRefresh();
    if (buttonSet.status === "D") {
        // 삭제처리의 응답인 경우
        await $c.win.closePopup();
    } else {
        await scwin.selectIsurDetail();
    }

    // frame.CloseFrame();

};

