/**
 * @method
 * @name txb_INCDEC_APPL_LIST_SHRS_onkeyup
 * @description 변경상장 > 기타수량감소 > 세부 > 증감증권수 onkeyup
 * @param {*} keycode keycode
 * @param {*} skeycode skeycode
 * @returns {void}
 * @hidden N
 */
scwin.txb_INCDEC_APPL_LIST_SHRS_onkeyup = function(keycode, skeycode) {
    // 변경상장 > 기타수량감소 > 세부 > 증감증권수 onkeyup

    if ($c.ut.trim(txb_INCDEC_APPL_LIST_SHRS.getValue()) === "-0") {
        txb_INCDEC_APPL_LIST_SHRS.setValue("0");
    }
    let rsltCalc = 0;
    if ($c.ut.trim(txb_INCDEC_APPL_LIST_SHRS.getValue()) === "" || $c.ut.trim(txb_INCDEC_APPL_LIST_SHRS.getValue()) === "-") {
        // 변경전 증권수
        rsltCalc = parseInt(txb_CHG_PRE_LIST_SHRS.getValue()); //+ parseInt(txb_NAPPL_SHRS.text);

    } else {
        // 변경전 증권수 + 증감증권수 +미반영 증권수
        rsltCalc = parseInt(txb_CHG_PRE_LIST_SHRS.getValue()) + parseInt(txb_INCDEC_APPL_LIST_SHRS.getValue());
    }
    txb_CHG_AF_LIST_SHRS.setValue(rsltCalc);
};

/**
 * @method
 * @name grd_fielList_OnDblClick
 * @description 파일다운로드
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_fielList_OnDblClick = function(row, colid) {
    // 파일다운로드
    if (row === 0) return;
    if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) === 0) {
        $c.dn.fn_filedown(scwin.vBzProcsNo, dts_fileList.getCellData(row, "ATTACH_SEQ"));
    }
};

/**
 * @method
 * @name btn_file1_onclick
 * @description 「파일추가」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_file1_onclick = async function() {
    if (dts_fileList.getRowCount() === 5) {
        await $c.win.alert("더이상 추가하실 수 없습니다.");
        return;
    }
    dts_fileList.insertRow();
    inf_find.open();
    if (inf_find.getValue() !== "") {
        if (!$c.lcd.checkBadExt(inf_find.getValue())) {
            await $c.win.alert("해당파일은 첨부하실 수 없습니다.");
            dts_fileList.removeRow(dts_fileList.getRowPosition());
            inf_find.setValue("");
            return;
        }
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "ATTACH_FILE_NM", inf_find.getValue());
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ", "0");
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileUrl", inf_find.getValue());

        // file_name.value = inf_find.Value;

    } else {
        dts_fileList.removeRow(dts_fileList.getRowPosition());
    }
    if (!scwin.canUploadFile()) {
        await $c.win.alert('30MB 이하의 파일만 첨부 가능합니다.');
        dts_fileList.removeRow(dts_fileList.getRowPosition());
        return;
    }
    inf_find.setValue("");
};

