/**
 * @method
 * @name dts_Isu_OnLoadCompleted
 * @description 신규처리에 의한 조회인지,  수정에 의한 조회인지를 구별
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Isu_OnLoadCompleted = async function(rowcount) {
    // 신규처리에 의한 조회인지,  수정에 의한 조회인지를 구별
    if (scwin.vBzProcsNo === "") {
        buttonSet.setInsertStatus();
    } else {
        $c.stf.setButtonSetWithDate(edt_CHG_LIST_DD, false);
        $c.stf.setButtonSetWithDate2(scwin.vDisclsYn);

        // 수량감소 가 아닌 경우 (추가상장,신규상장)
        // 저장,수정,삭제, 안내문 서식 안보이게 처리
        if (scwin.vListBzTpCd !== "789") {
            btn_Dscl.setBackgroundImage("../img/btn_make_info_d.gif");
            btn_Dscl.setDisabled(true);
            btn_Save.setBackgroundImage("../img/btn_save_d.gif");
            btn_Save.setDisabled(true);
            btn_Update.setBackgroundImage("../img/btn_modify_d.gif");
            btn_Update.setDisabled(true);
            btn_Delete.setBackgroundImage("../img/btn_delete_d.gif");
            btn_Delete.setDisabled(true);
        }
    }

    // 첨부파일 조회
    await scwin.fileSync();
};

/**
 * @method
 * @name txb_CHG_PRE_LIST_SHRS_onkeyup
